for sa,za,sb,zb in [(20,5,30,3),(30,3,20,4),(50,5,50,10)]:
 a=sa/za;b=sb/zb;ratio=a/b;add('machine','変圧器の並行運転',f'変圧比が同じでX/R比も等しい変圧器A（{sa}kVA、%Z={za}）とB（{sb}kVA、%Z={zb}）を並行運転する。分担容量SA/SBはどれか。',[f'{b/a:g}',f'{ratio:g}',f'{ratio+1:g}',f'{ratio+2:g}'],1,[f'同じ条件の分担比は (定格容量A/%ZA)/(定格容量B/%ZB)。',f'({sa}/{za})/({sb}/{zb})={ratio:g}。'],'SA/SB=(SnA/zA)/(SnB/zB)')
law=[('電気事業法・保安の責務','この問題冊子で、技術基準に適合するよう維持する義務の主体はどれか。',['設備を設置する者','設備の利用者全員','機器の販売店だけ','検査機関だけ'],0,['設置する者の義務と、主任技術者が担う保安の監督を分ける。','添付の法規問1では「設置」「するように維持」が対応する。']),('電気事業法・保安の責務','主任技術者を選任する主な目的として、添付の法規問1に合うものはどれか。',['機器販売の促進','保安の監督をさせる','請求書の作成','電力取引価格の決定'],1,['工事・維持・運用に関する保安の監督が役割。','機器を直接製造・販売する役割とは異なる。']),('地域独立系統','地域の電力系統を大系統から切り離して運用するとき、特に維持が必要な組合せはどれか。',['色と形','価格と在庫','電圧と周波数','面積と重量'],2,['需給の不均衡は周波数や電圧に影響する。','主電源・制御・保護が協調して運用する。']),('系統連系の利点と課題','系統連系の利点として適切なものはどれか。',['短絡電流が必ず0になる','事故の影響が絶対に広がらない','無制限に融通できる','予備力を共有し供給信頼度を高められる'],3,['融通により互いに支援できる。','ただし連系容量、安定度、短絡容量などの制約は残る。']),('電力設備の過負荷','一定時間の過負荷容量を検討する際、直接関係するものはどれか。',['発熱と冷却条件','銘板の色','敷地の名称','担当者の人数だけ'],0,['発熱は主に電流、冷却は温度・風・冷却装置などに依存する。','時間制限や絶縁寿命を含めて判断する。']),('ガスタービン発電所の監視','発電設備の保護装置を整理するとき、適切な考え方はどれか。',['出力値だけ見ればよい','検出する異常と遮断・停止の動作を対応させる','監視方式は設備によらず同じ','温度異常は保護と無関係'],1,['回転・温度・制御電源などの異常と、必要な保護動作を分けて整理する。','施設条件と適用する条文に戻って確認する。'])]
